mapper.select:
SELECT t1.* FROM `meattrade_pork_arrange_detail` t1
t1.pic_paths is NOT NULL AND (t1.transfer_status is NULL or t1.transfer_status = false) AND (t1.transfer_number < #{transferNumber} or t1.transfer_number is null)
limit #{querySize}

select pa.place as `id`, count(pa.id) as `number` from meattrade_pork_arrange_detail pa
pa.tenant = #{param.tenant} and pa.place is not null and pa.place != ''
and pa.place in
#{placeId}
AND pa.pork_arrange_time BETWEEN #{param.period.begin} AND #{param.period.end}
group by pa.place
